import csv, json, sys, argparse
from decimal import Decimal, ROUND_HALF_UP

# rates.json format changed in Aug (see rates_old.json for the previous USD-per-unit table)
def convert(amount, currency, rates):
    """Convert amount from `currency` to USD.
    rates maps currency -> units of that currency per 1 USD.
    So to convert TO USD: usd = amount / rate.
    Empty/missing currency is treated as USD (rate=1).
    """
    rate = rates.get(currency) if currency else rates.get("USD", 1.0)
    if rate is None:
        rate = 1.0  # unknown currency treated as USD
    return Decimal(str(amount)) / Decimal(str(rate))

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("input")
    ap.add_argument("-o", required=True)
    a = ap.parse_args()

    rates = json.load(open("rates.json"))
    totals = {}
    n = 0
    skipped = 0

    for row in csv.DictReader(open(a.input)):
        raw_amount = row.get("amount", "").strip()
        if not raw_amount:
            skipped += 1
            continue
        try:
            amt = Decimal(raw_amount)
        except Exception:
            skipped += 1
            continue

        currency = row.get("currency", "").strip() if row.get("currency") else ""
        if not currency:
            currency = "USD"

        usd = convert(amt, currency, rates)
        merchant = row.get("merchant", "").strip().lower()
        totals[merchant] = totals.get(merchant, Decimal("0")) + usd
        n += 1

    # Round totals using ROUND_HALF_UP
    rounded_totals = {}
    for k, v in totals.items():
        rounded_totals[k] = float(v.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

    out = {"totals_usd": rounded_totals, "skipped": skipped, "rows": n}
    json.dump(out, open(a.o, "w"))

if __name__ == "__main__":
    main()
PYEOF"}

